import pleaseai from '@pleaseai/eslint-config'

export default pleaseai({
  // Lint the docs site's Astro components (apps/docs).
  astro: true,
  ignores: [
    // Generated by Astro / Nimbus in the docs app (already gitignored there).
    'apps/docs/.astro/**',
    'apps/docs/.nimbus/**',
    // Nimbus UI primitives, kept byte-identical to upstream so
    // `nimbus-docs diff --apply` / `nimbus-docs add <slug> --overwrite` can
    // update them cleanly. Local edits there are minimal and reviewed by hand.
    'apps/docs/src/components/ui/**',
    // Upstream Nimbus layout, unmodified. Its `<script is:inline>` nested in
    // a JSX expression sends eslint-plugin-astro's indent fixes into a loop.
    'apps/docs/src/layouts/DocsLayout.astro',
    // Generated by `bun run generate` (smol-toml's layout); the sync test
    // checks it against @pleaseai/eslint-config instead.
    'packages/bun-lint-config/lint.toml',
  ],
})
